import{_ as a,o as n,c as o,j as e,a as r}from"./chunks/framework.Bd7kzaCy.js";const m=JSON.parse('{"title":"D.08　发展、心理经验、治疗理论与专业边界","description":"","frontmatter":{"title":"D.08　发展、心理经验、治疗理论与专业边界"},"headers":[],"relativePath":"theory/appendix-d/d-08.md","filePath":"theory/appendix-d/d-08.md"}'),l={name:"theory/appendix-d/d-08.md"};function d(s,t,p,i,c,u){return n(),o("div",null,[...t[0]||(t[0]=[e("div",{class:"theory-source"},[e("h1",{id:"section-d-08",tabindex:"-1"},[r("D.08　发展、心理经验、治疗理论与专业边界 "),e("a",{class:"header-anchor",href:"#section-d-08","aria-label":'Permalink to "D.08　发展、心理经验、治疗理论与专业边界 {#section-d-08}"'},"​")]),e("p",null,"正文连接：§2.11；§9；§13.5；§16.12—16.14。研究入口：08.01—08.16。"),e("p",null,"发展、依恋、心理动力、学习、创伤、家庭系统、支持与诊断研究，和IFS、CBT、DBT、EMDR、心智化、图式治疗等具体方案，不能合成一条人格成熟阶梯。每种研究先保留它自己的对象：主观经验、量表、临床分类、形成过程、维持机制、整包治疗或某个组成成分。"),e("p",null,"一种治疗包有益，不说明理论所述的每个机制均已识别；机制仍有争论，也不自动取消已经支持的有限效果。治疗关系、生活资源、疼痛、实践练习和社会支持应保有实际位置。身体放松、情绪减轻或一个叙述变得连贯，均不能独自认证某段历史记忆的真实性。"),e("p",null,"框架只提供非临床状态、情境、隐私及责任的记录边界。它不凭快速情绪、慢变量或关系冲突诊断疾病，也不把拒绝披露写成病理证据。专业诊断、行政给付资格、本人认同和生活目标分别判断；没有理想的“健康过去”，不妨碍据当下安全、需要与支持条件讨论改变。"),e("p",null,"教学例：一个人获得稳定住所后生活更可安排，但某项症状评分尚未改变。住房成果可以成立，临床结论保持有限；不能把未改善的评分抹成改善，也不能据此否定住房的价值。临床判断与高风险照护仍须专业过程；所谓专业资格，更不能用来认证一个人的“本质”。"),e("p",null,"需要支持不等于结果失去资格。若任务是表达意愿，持续辅助可以是完成任务的构成条件；若任务是独立迁移技能，则需另有适当的无辅助测量。治疗包效果、成分比较、统计中介、专有机制和个人适用性各有可成立的有限答案，不能由其中一项替其余项目结案，也不能以未证明独有机制撤销已有的有限效果。"),e("p",null,"专题定位：08.01 发展心理学：皮亚杰、维果茨基、埃里克森；08.02 依恋、关系安全与分离：Bowlby、Ainsworth；08.03 心理动力与无意识：弗洛伊德、荣格及其批评；08.04 学习、强化与习得性无助；08.05 创伤、应激、解离与恢复；08.06 家庭系统与代际传递；08.07 复原、治疗与社会支持；08.08 诊断分类、神经多样性与污名；08.09 多迷走神经与身体取向理论；08.10 精神动力学人格结构的具体模型；08.11 内部家庭系统 IFS；08.12 认知行为治疗 CBT；08.13 辩证行为治疗 DBT；08.14 EMDR 与经验整合；08.15 心智化与心智化治疗；08.16 图式治疗。")],-1)])])}const f=a(l,[["render",d]]);export{m as __pageData,f as default};
